parameters.functionCode:
// Update state with the result of the action
const currentState = items[0].json.state;
const toolResult = items[0].json.result || 'Action completed';
const reasoning = items[0].json.ai_response.reasoning || 'No reasoning provided';
const stepCount = parseInt(items[0].json.step_count) + 1;

const newState = `Previous action: ${reasoning}\nResult: ${toolResult}\nStep ${stepCount} completed.`;

return [{
  json: {
    ...items[0].json,
    state: newState,
    step_count: stepCount.toString(),
    completed: false
  }
}];

